const $=s=>document.querySelector(s),app=$('#app'),cache=new Map(),replayCache=new Map();
let I,D,audit,photos={players:{}},state={season:'Fall 2026',kind:'all',session:'all',team:'centre',person:'all',type:'all',hand:'all',count:'all',tags:'reviewed',minimum:20,minPA:5,profileRole:'auto',labX:'ahb',labY:'ivb',role:'hit',query:'',outcomes:'full',compareA:'',compareB:'',sensitivity:false,...roomDefaults,...studioDefaults},current,renderId=0,replayFrame=0,replayTime=0,replaySelected=null;
try{Object.assign(state,JSON.parse(sessionStorage.getItem('atlas-state')||'{}'))}catch{}
const nav=[['overview','◈','Overview'],['players','♙','Players'],['pitching','◎','Pitching'],['hitting','⌁','Hitting'],['games','▦','Game room'],['studio','✦','Analysis studio'],['defense','◇','Defense'],['discover','✧','Discover'],['replay','▷','Replay'],['data','⊞','Data & methods']];
const slug=s=>s.toLowerCase().replace(' ','-');
const player=id=>I.players[id]||{display:'Unknown player',name:'Unknown player',centre:false};
const pname=id=>esc(player(id).display);
const avatar=(id,size='card')=>portrait(player(id),photos,size);
const searchableName=p=>`${p.display} ${p.name} ${portraitFor(p,photos)?.sourceName||''} ${p.name.includes('Tristan')?'Tristen':''} ${p.name.includes('Taylor, Wes')?'Wesley':''}`.toLowerCase();
const plink=id=>`<a class="player-link" href="#player/${id}">${avatar(id,'tiny')}<span>${pname(id)}</span></a>`;
const initials=id=>player(id).display.split(' ').filter(Boolean).map(s=>s[0]).slice(0,2).join('');
const pageRoute=()=>location.hash.slice(1).split('?')[0]||'overview';
const currentPage=()=>pageRoute().split('/')[0];
const go=r=>{location.hash=r};
const note=t=>`<div class="inline-note"><span>ⓘ</span><div>${t}</div></div>`;
const empty=(title,text,link='')=>`<div class="empty"><h3>${title}</h3><p>${text}</p>${link}</div>`;
const stat=(label,value,sub)=>`<div class="stat"><div class="label">${label}</div><div class="value">${value}</div><div class="sub">${sub}</div></div>`;
const card=(title,sub,body,chip='')=>`<section class="card"><div class="card-head"><div><h3>${title}</h3><p>${sub}</p></div>${chip?`<span class="chip">${chip}</span>`:''}</div>${body}</section>`;
const heading=(eyebrow,title,sub,action='')=>`<div class="heading"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div>${action}</div>`;
function opt(v,label,selected){return`<option value="${esc(v)}" ${String(v)===String(selected)?'selected':''}>${esc(label)}</option>`}
const select=(key,label,options)=>`<label><span class="filter-label">${label}</span><select data-state="${key}" aria-label="${label}">${options.map(([v,l])=>opt(v,l,state[key])).join('')}</select></label>`;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2300)}
function save(){try{sessionStorage.setItem('atlas-state',JSON.stringify(state))}catch{}}
async function fetchJSON(path){const r=await fetch(path);if(!r.ok)throw Error(`Could not load ${path} (${r.status}).`);return r.json()}
async function load(season){if(!cache.has(season))cache.set(season,fetchJSON(`data/${slug(season)}.json`).then(d=>({pitches:unpack(d.pitches),pas:unpack(d.pas),pbp:unpack(d.pbp)})).catch(e=>{cache.delete(season);throw e}));return cache.get(season)}
async function allData(){const ds=[];for(let i=0;i<I.seasons.length;i+=3)ds.push(...await Promise.all(I.seasons.slice(i,i+3).map(load)));return{pitches:ds.flatMap(d=>d.pitches),pas:ds.flatMap(d=>d.pas),pbp:ds.flatMap(d=>d.pbp)}}
function gameMatch(g){const game=I.games[g];return(state.kind==='all'||game.kind===state.kind)&&(state.session==='all'||String(g)===state.session)}
function pitchMatch(p,role='pitch',person=true){return gameMatch(p.g)&&(state.team==='all'||(state.team==='centre'?player(p[role==='hit'?'b':'p']).centre:!player(p[role==='hit'?'b':'p']).centre))&&(!person||state.person==='all'||String(p[role==='hit'?'b':'p'])===state.person)&&(state.type==='all'||p.t===state.type)&&(state.hand==='all'||p.bats.startsWith(state.hand))&&(state.count==='all'||(state.count==='two'?p.strikes===2:state.count==='first'?p.balls===0&&p.strikes===0:state.count==='ahead'?p.strikes>p.balls:p.balls>p.strikes))}
function pitches(role='pitch',person=true){return current.pitches.map(p=>state.tags==='source'?{...p,t:p.baseType}:p).filter(p=>pitchMatch(p,role,person))}
function pas(role='hit',person=true){let source=role==='hit'?outcomePool():trackedPas();return source.filter(p=>gameMatch(p.g)&&(state.team==='all'||(state.team==='centre'?player(p[role==='hit'?'b':'p']).centre:!player(p[role==='hit'?'b':'p']).centre))&&(!person||state.person==='all'||String(p[role==='hit'?'b':'p'])===state.person)&&(!state.sensitivity||!p.scenario&&!p.repeat))}
function sourceLabel(){if(state.outcomes!=='full'||state.team!=='centre'||!current.pbp.some(p=>gameMatch(p.g)))return 'Tracked PA';return current.pas.some(p=>gameMatch(p.g)&&I.games[p.g].kind!=='Spring Game')?'PBP games + tracked practice':'Full-game PBP'}
function filters({person=false,role='pitch',advanced=false,team=true,session=true}={}){
 const availableGames=I.games.filter(g=>(state.season==='All seasons'||g.season===state.season)&&(state.kind==='all'||g.kind===state.kind));const kinds=[...new Set(availableGames.map(g=>g.kind))];
 let html=select('season','Season',[['All seasons','All seven seasons'],...I.seasons.slice().reverse().map(s=>[s,s])])+select('kind','Competition',[['all','All competitions'],...['Spring Game','Spring Intrasquad','Fall Intrasquad','Fall Scrimmage'].map(k=>[k,k])])+(session?select('session','Session',[['all','All sessions'],...availableGames.slice().sort((a,b)=>b.date.localeCompare(a.date)).map(g=>[g.id,g.label])]):'');
 if(team)html+=select('team','Team',[['centre','Centre'],['opponents','Opponents'],['all','Both teams']]);
 if(person){const ids=[...new Set(current.pitches.filter(p=>gameMatch(p.g)&&(state.team==='all'||(state.team==='centre'?player(p[role==='hit'?'b':'p']).centre:!player(p[role==='hit'?'b':'p']).centre))).map(p=>p[role==='hit'?'b':'p']))].sort((a,b)=>player(a).name.localeCompare(player(b).name));html+=select('person',role==='hit'?'Hitter':'Pitcher',[['all',role==='hit'?'All hitters':'All pitchers'],...ids.map(id=>[id,player(id).display])])}
 if(advanced)html+=select('type','Pitch type',[['all','All pitch types'],...Object.keys(groups(current.pitches,'t')).sort().map(t=>[t,t])])+select('hand','Batter side',[['all','Both sides'],['R','Right-handed'],['L','Left-handed']])+select('count','Count',[['all','All counts'],['first','0–0'],['two','Two strikes'],['ahead','Pitcher ahead'],['behind','Pitcher behind']]);
 return`<div class="filters">${html}<button data-action="reset" style="align-self:flex-end">Reset</button></div>`;
}
function shell(){app.innerHTML=`<aside class="sidebar"><a class="brand" href="#overview" aria-label="Centre Atlas home"><span class="brand-mark">C</span><span>ATLAS<small>CENTRE BASEBALL</small></span></a><div class="nav-label">The field guide</div><nav class="nav" aria-label="Main navigation">${nav.map(([id,icon,label])=>`<a href="#${id}" data-nav="${id}"><span class="nav-icon" aria-hidden="true">${icon}</span>${label}</a>`).join('')}</nav><div class="sidebar-foot"><span class="live-dot"></span> Through Oct 24, 2026<br>Seven seasons. One story.<br><a href="https://github.com/AustinsAnalytics/centre-baseball-atlas" target="_blank" rel="noopener">AustinsAnalytics ↗</a></div></aside><div class="workspace"><header class="topbar"><div class="breadcrumb">Centre Baseball <span style="margin:0 9px">/</span> <b id="crumb">Field guide</b></div><div class="top-actions"><button class="search-trigger" data-action="search"><span aria-hidden="true">⌕</span> Search players, stats, tools… <kbd>⌘ K</kbd></button><button class="theme-button" data-action="theme" aria-label="Switch color mode"></button></div></header><main id="main" class="main" tabindex="-1"></main></div>`;themeButton()}
function themeButton(){const dark=document.documentElement.dataset.theme==='dark';const b=$('.theme-button');if(b){b.innerHTML=`<span aria-hidden="true">${dark?'☀':'☾'}</span>${dark?'Normal mode':'Dark mode'}`;b.setAttribute('aria-label',dark?'Switch to normal mode':'Switch to dark mode')}}
function toggleTheme(){const theme=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=theme;try{localStorage.setItem('atlas-theme',theme)}catch{}themeButton()}
function footer(){return`<footer class="footer"><span>CENTRE ATLAS · ${int(I.totals.pitches)} pitches · 2023–2026</span><span>Measurements have limits. <a href="#data">See sources & definitions ↗</a></span></footer>`}
async function render(){const token=++renderId;cancelAnimationFrame(replayFrame);const pg=currentPage();if(pg==='studio'&&state.studioMode==='change')state.session='all';document.querySelectorAll('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===pg||(pg==='player'&&a.dataset.nav==='players')||(pg==='compare'&&a.dataset.nav==='players')));$('#crumb').textContent=nav.find(n=>n[0]===pg)?.[2]||'Player notebook';$('#main').innerHTML='<div class="loading">Loading the field guide…</div>';save();
 try{const d=state.season==='All seasons'?await allData():await load(state.season);if(token!==renderId)return;current={...d,pitches:d.pitches.map(p=>state.tags==='source'?{...p,t:p.baseType,reviewedType:p.t}:p)};let html;switch(pg){case'players':html=playersPage();break;case'player':html=await profilePage(Number(pageRoute().split('/')[1]));break;case'compare':html=comparePage();break;case'pitching':html=pitchingPage();break;case'hitting':html=hittingPage();break;case'studio':{const historyRows=state.studioMode==='change'&&state.season!=='All seasons'?[...d.pitches,...(state.studioPeriod===state.season?[]:(await load(I.seasons.includes(state.studioPeriod)?state.studioPeriod:'Fall 2025')).pitches)].map(p=>state.tags==='source'?{...p,t:p.baseType}:p):[];html=studioPage({I,state,rows:studioRows(),allCurrent:current.pitches,historyRows,filters,select,heading,card,note,table,avatar});break}case'games':html=roomPage({I,state,rows:pitches(state.roomRole),types:Object.keys(groups(current.pitches,'t')).sort(),filters,select,heading,card,stat,note,table});break;case'defense':html=await defensePage();break;case'discover':html=discoverPage();break;case'replay':html=await replayPage();break;case'data':html=await dataPage();break;default:html=overviewPage()}
 if(token!==renderId)return;$('#main').innerHTML=html+footer();bindLocal();if(pg==='replay')drawReplay(1);document.title=`${pg==='player'?player(Number(pageRoute().split('/')[1])).display:nav.find(n=>n[0]===pg)?.[2]||'Overview'} · Centre Atlas`;
 }catch(e){if(token===renderId)$('#main').innerHTML=empty('The data could not be loaded.',esc(e.message),'<button data-action="retry">Try again</button>');console.error(e)}
}
function studioRows(){return pitches(state.studioRole).filter(p=>studioPitchMatch(p,state))}
function overviewPage(){const pp=pitches('pitch'),bp=pitches('hit'),ps=stats(pp,pas('pitch')),bs=stats(bp,pas('hit')),ss=state.season==='All seasons'?I.summary:I.summary.filter(s=>s.season===state.season),active=I.games.filter(g=>gameMatch(g.id)&&(state.season==='All seasons'||g.season===state.season));const heroRows=pp.filter(p=>finite(p.ahb)&&finite(p.ivb));
 return heading('THE COLONELS’ FIELD GUIDE','Baseball, connected.','Find the patterns behind the box score. Follow a player, explore a pitch, or watch a ball take flight.')+filters()+questionBar()+`<section class="hero"><div class="hero-copy"><div class="eyebrow">${esc(state.season)} · ${active.filter(g=>g.tracked).length} tracked sessions</div><h2 class="hero-title">Every pitch has<br><em>another layer.</em></h2><p>${state.season==='Fall 2026'?(state.kind==='all'&&state.session==='all'?'Four intrasquads. Two Lindsey Wilson scrimmages. An early look at the arms, approaches, and contact shaping the next Centre season.':`${active.filter(g=>g.tracked).length} selected tracked sessions. An early look at pitch shapes, decisions and contact within this view.`):'Connect pitch movement, decisions at the plate, and the people behind the numbers. Start with a question. Follow the evidence.'}</p><div class="hero-links"><a href="#players">Explore the players ↗</a><a href="#discover">Find something unexpected</a></div></div><div class="hero-art"><span class="hero-tag">THE SHAPE OF THIS SEASON</span>${scatter(heroRows,{hero:true,height:340,width:500})}</div></section><div class="stat-grid">${stat(state.team==='centre'?'Centre pitching':state.team==='opponents'?'Opponent pitching':'Both teams pitching',int(ps.n),'eligible tracked pitches')}${stat('Missed bats',pct(ps.whiff),`${int(ps.whiffs)} whiffs / ${int(ps.swings)} swings`)}${stat('Batting average',slash(bs.avg),`${int(bs.h)} H / ${int(bs.ab)} AB · ${sourceLabel()}`)}${stat('Hard contact',pct(bs.hard),`${bs.hardN} at 95+ / ${bs.evN} usable EV`)}</div>`+
 studioLaunchpad(state)+`<div class="grid-wide">${card('The seven-season view','All tracked pitches; filled area shows Centre pitching.',`<div class="timeline">${I.summary.map(s=>`<button class="season-bar ${s.season===state.season?'current':''}" data-season="${s.season}" aria-label="Show ${s.season}, ${s.n} pitches"><b>${int(s.n)}</b><span class="bar" style="height:${Math.max(6,s.n/11498*125)}px"><i style="height:${100*s.pitching.n/s.n}%"></i></span><span>${s.season.replace(' ','<br>')}</span></button>`).join('')}</div><p class="chart-note">Spring results include additional PBP-only games. Scrimmages and practice sessions remain identifiable.</p>`)}${card('The arsenal at a glance','Pitch usage in the selected sample.',arsenal(pp),`${Object.keys(groups(pp,'p')).length} pitchers`)}</div>`+
 `<div class="section-head"><h2>A closer look</h2><a href="#discover">Open the discovery notebook ↗</a></div><div class="grid3">${insightCards(pp,bp).slice(0,3).join('')}</div>`+
 note(`${state.season.startsWith('Fall')?'<strong>Early evidence, not a verdict.</strong> Fall results include practice conditions and uneven samples. ':'<strong>Two lenses, kept separate.</strong> '}${sourceLabel()!=='Tracked PA'?'Batting outcomes use PBP games plus any selected tracked practices/scrimmages; movement and contact use TrackMan coverage.':'Batting outcomes use completed tracked plate appearances.'} EV is available for ${bs.evN} of ${bs.bip} selected balls in play.`);
}
function insightCards(pp,bp){let cards=[];const make=(n,title,value,text,link,label='Explore this pattern')=>`<article class="card insight"><span class="insight-no">FIELD NOTE ${n}</span><h3>${title}</h3><div class="insight-value">${value}</div><p>${text}</p><a href="${link}">${label} ↗</a></article>`;
 const pairs=[];for(const[id,rs]of Object.entries(groups(pp,'p'))){const ts=Object.entries(groups(rs.filter(p=>finite(p.ahb)&&finite(p.ivb)&&finite(p.v)),'t')).filter(([t,a])=>a.length>=12);for(let i=0;i<ts.length;i++)for(let j=i+1;j<ts.length;j++){const[a,ar]=ts[i],[b,br]=ts[j],va=mean(ar.map(p=>p.v)),vb=mean(br.map(p=>p.v)),dx=mean(ar.map(p=>p.ahb))-mean(br.map(p=>p.ahb)),dy=mean(ar.map(p=>p.ivb))-mean(br.map(p=>p.ivb));if(Math.abs(va-vb)<=4)pairs.push({id,a,b,ar,br,d:Math.hypot(dx,dy),gap:Math.abs(va-vb)})}}
 pairs.sort((a,b)=>b.d-a.d);if(pairs.length){const p=pairs[0];cards.push(make('01','Similar speed. Different destination.',`${fmt(p.d)} in`,`${player(p.id).display}’s ${p.a.toLowerCase()} and ${p.b.toLowerCase()} are only ${fmt(p.gap)} mph apart, but their mean movement vectors differ by ${fmt(p.d)} inches (${p.ar.length} / ${p.br.length} pitches). Shape separation does not establish tunneling.`,`#player/${p.id}`))}
 const approaches=Object.entries(groups(bp,'b')).map(([id,rs])=>{const st=stats(rs),z=rs.filter(p=>zone(p));return{id,st,z,zsw:z.filter(swing).length}}).filter(p=>p.st.outside>=25&&p.z.length>=25).sort((a,b)=>(b.zsw/b.z.length-b.st.chase)-(a.zsw/a.z.length-a.st.chase));if(approaches.length){const p=approaches[0],gap=p.zsw/p.z.length-p.st.chase;cards.push(make('02','Aggressive in the right places.',`${fmt(gap*100,0)} pp`,`${player(p.id).display} swings at ${pct(p.zsw/p.z.length)} of ${p.z.length} in-zone pitches, versus ${pct(p.st.chase)} of ${p.st.outside} outside. That separation describes selectivity—not whether every take was correct.`,`#player/${p.id}`))}
 const two=pp.filter(p=>p.strikes===2&&p.loc&&!zone(p)),zero=pp.filter(p=>p.balls===0&&p.strikes===0&&p.loc&&!zone(p));if(two.length>=20&&zero.length>=20){const a=two.filter(swing).length,b=zero.filter(swing).length;cards.push(make('03','The count changes the invitation.',`${pct(a/two.length)} vs ${pct(b/zero.length)}`,`Out-of-zone swing rate against this pitching sample with two strikes versus 0–0 (${a}/${two.length} vs ${b}/${zero.length}). Count, pitch mix, hitter and location all change together; this is a descriptive split.`, '#pitching'))}
 const usable=bp.filter(p=>finite(p.ev)&&finite(p.la)),ground=usable.filter(p=>p.la<8),air=usable.filter(p=>p.la>=8&&p.la<=32);if(ground.length>=8&&air.length>=8)cards.push(make('04','Hard contact has a launch-angle story.',`${fmt(mean(air.map(p=>p.ev)))} mph`,`Average EV in the 8–32° launch window (${air.length} balls), compared with ${fmt(mean(ground.map(p=>p.ev)))} mph below 8° (${ground.length}). The comparison excludes ungraded or low-confidence launch measurements.`, '#hitting'));
 const release=[];for(const rs of Object.values(groups(pp,p=>p.p+'-'+p.g))){const ts=Object.entries(groups(rs.filter(p=>finite(p.rh)&&finite(p.rs)),'t')).filter(([t,a])=>a.length>=10);for(let i=0;i<ts.length;i++)for(let j=i+1;j<ts.length;j++){const[a,ar]=ts[i],[b,br]=ts[j],d=12*Math.hypot(mean(ar.map(p=>p.rh))-mean(br.map(p=>p.rh)),mean(ar.map(p=>p.rs))-mean(br.map(p=>p.rs)));release.push({id:rs[0].p,g:rs[0].g,a,b,n:ar.length,m:br.length,d})}}release.sort((a,b)=>b.d-a.d);if(release.length){const p=release[0];cards.push(make('05','A release cue to investigate.',`${fmt(p.d)} in`,`${player(p.id).display}’s ${p.a.toLowerCase()} and ${p.b.toLowerCase()} release centroids were ${fmt(p.d)} inches apart in ${I.games[p.g].label} (${p.n}/${p.m} pitches). One outing’s geometry; this alone does not show a visible tell or a mechanical problem.`,`#player/${p.id}`))}
 if(!cards.length)cards.push(make('01','A sample still taking shape.',int(pp.length),'This selection is too small for the notebook’s minimum sample rules. Broaden the session or player filters to find supported comparisons.','#overview','Broaden the view'));
 return cards.map((c,i)=>c.replace(/FIELD NOTE \d+/,`FIELD NOTE ${String(i+1).padStart(2,'0')}`));
}
function table(headers,rows,id=''){return`<div class="table-scroll"><table class="data-table" ${id?`id="${id}"`:""}><thead><tr>${headers.map((h,i)=>`<th scope="col" data-sort="${i}" tabindex="0" title="Sort by ${esc(h)}">${h} <span aria-hidden="true">↕</span></th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map((v,i)=>`<td>${v}</td>`).join('')}</tr>`).join('')}</tbody></table></div>${rows.length?'':empty('No matching rows.','Broaden the filters or reduce the minimum sample.')}`}
function playersPage(){const ids=[...new Set([...current.pitches.filter(p=>gameMatch(p.g)).flatMap(p=>[p.p,p.b]),...current.pbp.filter(p=>gameMatch(p.g)).map(p=>p.b)])].filter(id=>(state.team==='all'||(state.team==='centre'?player(id).centre:!player(id).centre))&&searchableName(player(id)).includes(state.query.toLowerCase())).sort((a,b)=>player(a).name.localeCompare(player(b).name));
 return heading('PEOPLE, NOT JUST LEADERBOARDS','The player notebook.','A clear view of each player’s arsenal, approach, contact, and development over time.', '<a class="button-link" href="#compare">Compare players ⇄</a>')+filters()+`<div class="table-controls"><input type="search" id="roster-search" placeholder="Find a player…" value="${esc(state.query)}" aria-label="Search roster"><p class="small">${ids.length} players in this selection</p></div><div class="player-grid" id="player-cards">${ids.map(id=>{const pp=current.pitches.filter(p=>p.p===id&&gameMatch(p.g)),bp=current.pitches.filter(p=>p.b===id&&gameMatch(p.g)),ps=stats(pp),bs=stats(bp,outcomePool(id).filter(p=>p.b===id&&gameMatch(p.g)));const pitcher=pp.length>bp.length;return`<a class="card player-card" href="#player/${id}" data-name="${esc(searchableName(player(id)))}"><div class="player-top">${avatar(id)}<div><h3>${pname(id)}</h3><p>${pitcher?'Pitcher':'Hitter'}${pp.length&&bp.length?' · two-way tracking':''} · ${player(id).centre?'Centre':esc(player(id).team)}</p></div></div><div class="player-metrics">${pitcher?`<div><b>${int(ps.n)}</b><span>PITCHES</span></div><div><b>${fmt(ps.velo)}</b><span>AVG MPH</span></div><div><b>${pct(ps.whiff)}</b><span>WHIFF / SW</span></div>`:`<div><b>${bs.pa}</b><span>PA</span></div><div><b>${slash(bs.avg)}</b><span>AVG</span></div><div><b>${fmt(bs.ev)}</b><span>EV · ${bs.evN} BIP</span></div>`}</div></a>`}).join('')}</div>${ids.length?'':empty('No players match.','Try a different name or season.')} `;
}

const labAxes={ahb:['Arm-side break (in)',-25,25],ivb:['Induced vertical break (in)',-25,25],v:['Velocity (mph)',50,100],spin:['Spin rate (rpm)',500,3500],rh:['Release height (ft)',3,8],ext:['Extension (ft)',3,9],rs:['Raw release side (ft)',-5,5],vaa:['Vertical approach angle (°)',-15,0]};
function labControls(){return `<div class="filters">${select('labX','Horizontal axis',Object.entries(labAxes).map(([k,v])=>[k,v[0]]))}${select('labY','Vertical axis',Object.entries(labAxes).map(([k,v])=>[k,v[0]]))}</div>`}
function labPlot(rows){const x=labAxes[state.labX]||labAxes.ahb,y=labAxes[state.labY]||labAxes.ivb;return scatter(rows,{x:state.labX,y:state.labY,domainX:x.slice(1),domainY:y.slice(1),labelX:x[0],labelY:y[0]})}

