function discoverPage(){const pp=pitches(),bp=pitches('hit'),c=insightCards(pp,bp),g=Object.entries(groups(pp,'p')).map(([id,rows])=>({id,rows,s:stats(rows)})).filter(x=>x.s.swings>=25).sort((a,b)=>b.s.whiff-a.s.whiff);return heading('THE DISCOVERY NOTEBOOK','Ask a better baseball question.','Patterns worth investigating, with the sample and the caveat attached. These notes recalculate with your selection.')+filters()+`<div class="grid2">${c.join('')}</div><div class="section-head"><h2>How stable is that whiff rate?</h2><span class="chip">95% Wilson intervals</span></div>${card('A percentage is a range of possibilities.','Small samples produce wider intervals. These quantify binomial sampling uncertainty, not opponent or pitch-mix effects.',g.length?whiffIntervals(g):empty('Not enough swings.','At least 25 swings per pitcher are required for this view.'))}${note('These notes use explicit descriptive rules, not generated scouting claims. They do not establish cause, future performance, pitch intent, or independent repeatability. Open a player notebook to inspect the underlying sample.')}`}
