async function copyText(text){try{await navigator.clipboard.writeText(text);toast('Copied.')}catch{toast('Clipboard unavailable. Select and copy the address from your browser.')}}
const viewKeys=['season','kind','session','team','person','type','hand','count','tags','outcomes','sensitivity','roomRole','rival','exactCount','inning','half','outs','bases','score','context','callFilter','roomQuery','labX','labY',...Object.keys(studioDefaults)];
function share(){const u=new URL(location.href);u.searchParams.delete('pitch');u.searchParams.set('view',JSON.stringify(Object.fromEntries(viewKeys.map(k=>[k,state[k]]))));history.replaceState(null,'',u);copyText(u.toString())}
function reset(){Object.assign(state,{kind:'all',session:'all',team:'centre',person:'all',type:'all',hand:'all',count:'all',query:'',minimum:20,...roomDefaults,studioCount:'all',studioCell:'all',studioPair:'all',studioBin:'all',studioArm:'all'});render()}
function setSeason(season){state.rival='all';state.season=season;state.kind=season.startsWith('Spring')?'Spring Game':'all';state.session='all';state.person='all';state.type='all';state.hand='all';state.count='all';save()}
function sortTable(th){const table=th.closest('table'),index=Number(th.dataset.sort),dir=th.dataset.dir==='asc'?'desc':'asc';table.querySelectorAll('th').forEach(h=>{h.removeAttribute('aria-sort');delete h.dataset.dir});th.dataset.dir=dir;th.setAttribute('aria-sort',dir==='asc'?'ascending':'descending');const rows=[...table.tBodies[0].rows],parse=text=>{const s=text.trim().replace(/,/g,'').replace(/%$/,'');return /^-?(?:\d+\.?\d*|\.\d+)$/.test(s)?Number(s):s.toLowerCase()};rows.sort((a,b)=>{const x=parse(a.cells[index].querySelector('.player-link>span:last-child')?.textContent??a.cells[index].textContent),y=parse(b.cells[index].querySelector('.player-link>span:last-child')?.textContent??b.cells[index].textContent);if(x==='—')return 1;if(y==='—')return-1;return(typeof x==='number'&&typeof y==='number'?x-y:String(x).localeCompare(String(y)))*(dir==='asc'?1:-1)});rows.forEach(r=>table.tBodies[0].appendChild(r))}
function bindLocal(){const question=$('#study-question-form');if(question)question.addEventListener('submit',e=>{e.preventDefault();const q=$('#study-question').value;openSearch();$('#global-search').value=q;searchResults(q)});const form=$('#room-search-form');if(form)form.addEventListener('submit',e=>{e.preventDefault();state.roomQuery=$('#room-search').value;state.roomPage=0;render()});const roster=$('#roster-search');if(roster)roster.addEventListener('input',e=>{const q=e.target.value.toLowerCase();document.querySelectorAll('.player-card').forEach(c=>c.hidden=!c.dataset.name.includes(q))});const rs=$('#replay-search');if(rs)rs.addEventListener('input',e=>{const q=e.target.value.toLowerCase();$('#replay-list').innerHTML=replayItems(replayRecords.filter(p=>`${player(p.b).display} ${player(p.p).display} ${p.result} ${I.games[p.g].label}`.toLowerCase().includes(q)))});const scrub=$('#replay-scrub');if(scrub)scrub.addEventListener('input',e=>{cancelAnimationFrame(replayFrame);$('#play-button').textContent='▶ Play';drawReplay(Number(e.target.value)/1000)});const au=$('#audit-search');if(au)au.addEventListener('input',e=>{const q=e.target.value.toLowerCase();$('#audit-table').innerHTML=auditTable(audit.filter(a=>`${a.pitcher} ${a.uid} ${a.original} ${a.candidate} ${a.season}`.toLowerCase().includes(q)).slice(0,100))});}
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.state){const key=el.dataset.state,val=el.value;state.roomPage=0;if(['season','kind','session','team','person','type','hand','count','studioArm'].includes(key))Object.assign(state,{studioCount:'all',studioCell:'all',studioPair:'all',studioBin:'all'});if(key==='season')setSeason(val);else{state[key]=['minimum','minPA'].includes(key)?Number(val):val;if(key==='kind'){state.session='all';state.person='all'}if(key==='team'){state.person='all';state.rival='all'}if(key==='compareA'&&pageRoute().startsWith('compare/'))history.replaceState(null,'','#compare')}render()}});
document.addEventListener('click',async e=>{const el=e.target.closest('button,a,circle,th');if(!el)return;if(el.classList.contains('skip')){e.preventDefault();$('#main').focus();return}
 if(el.dataset.query){openSearch();$('#global-search').value=el.dataset.query;searchResults(el.dataset.query);return}
 if(el.dataset.studioMode){state.studioMode=el.dataset.studioMode;Object.assign(state,{studioCount:'all',studioCell:'all',studioPair:'all',studioBin:'all'});if(state.studioMode==='contact'){state.studioRole='hit';state.person='all'}if(state.studioMode==='change'){state.session='all';if(state.kind==='all')state.kind=state.season.startsWith('Spring')?'Spring Intrasquad':'Fall Intrasquad';state.studioChange=state.studioRole==='hit'?'ev':'v'}render();return}
 if(el.dataset.studioRole){state.studioRole=el.dataset.studioRole;state.person='all';state.studioChange=state.studioRole==='hit'?'ev':'v';state.studioCount=state.studioCell=state.studioPair=state.studioBin='all';render();return}
 if(el.dataset.studioCount){state.studioCount=state.studioCount===el.dataset.studioCount?'all':el.dataset.studioCount;state.studioCell='all';render();return}
 if(el.dataset.studioCell){state.studioCell=state.studioCell===el.dataset.studioCell?'all':el.dataset.studioCell;render();return}
 if(el.dataset.studioPair){state.studioPair=state.studioPair===el.dataset.studioPair?'all':el.dataset.studioPair;render();return}
 if(el.dataset.studioBin){state.studioBin=state.studioBin===el.dataset.studioBin?'all':el.dataset.studioBin;render();return}
 if(el.dataset.roomRole){state.roomRole=el.dataset.roomRole;state.person='all';state.rival='all';state.roomPage=0;render();return}if(el.dataset.roomCount){state.exactCount=state.exactCount===el.dataset.roomCount?'all':el.dataset.roomCount;state.roomPage=0;render();return}if(el.dataset.roomPage!==undefined){state.roomPage=Number(el.dataset.roomPage);render();return}if(el.dataset.sequence){await openSequence(el.dataset.sequence);return}if(el.dataset.sequenceExport){const d=await sequenceData(el.dataset.sequenceExport);if(d)downloadCSV('centre-atlas-sequence.csv',pitchCSV(d.rows,I));return}if(el.dataset.copyPitchLink){pitchLink(el.dataset.copyPitchLink);return}
 if(el.dataset.close){$('#'+el.dataset.close).close();return}if(el.dataset.pitch){await inspectPitch(el.dataset.pitch);return}if(el.dataset.sort!==undefined){sortTable(el);return}
 if(el.dataset.searchPlayer){$('#search-dialog').close();const id=Number(el.dataset.searchPlayer);if(!player(id).seasons.includes(state.season)&&state.season!=='All seasons')setSeason(player(id).seasons.at(-1));go('player/'+id);if(currentPage()==='player')render();return}
 if(el.dataset.searchGame!==undefined){$('#search-dialog').close();const g=I.games[Number(el.dataset.searchGame)];setSeason(g.season);state.kind='all';state.session=String(g.id);Object.assign(state,roomDefaults);go(g.tracked?'games':'hitting');render();return}if(el.dataset.searchRoute){$('#search-dialog').close();go(el.dataset.searchRoute);return}if(el.dataset.searchSeason){$('#search-dialog').close();setSeason(el.dataset.searchSeason);go('overview');render();return}if(el.dataset.searchPitch){$('#search-dialog').close();await inspectPitch(el.dataset.searchPitch);return}
 if(el.dataset.jumpPlayer){$('#detail-dialog').close();if(state.season!=='All seasons'&&state.season!==el.dataset.inspectSeason)setSeason(el.dataset.inspectSeason);go('player/'+el.dataset.jumpPlayer);return}if(el.dataset.jumpReplay){$('#detail-dialog').close();setSeason(el.dataset.season);state.session=el.dataset.sessionId;state.team='all';replaySelected=el.dataset.jumpReplay;go('replay');render();return}if(el.dataset.copyUid){copyText(el.dataset.copyUid);return}
 if(el.dataset.replay){cancelAnimationFrame(replayFrame);replaySelected=el.dataset.replay;document.querySelectorAll('[data-replay]').forEach(b=>b.classList.toggle('selected',b.dataset.replay===replaySelected));$('#play-button').textContent='▶ Play';drawReplay(1);return}
 if(el.dataset.season){setSeason(el.dataset.season);render();return}if(el.dataset.outcomes){state.outcomes=el.dataset.outcomes;render();return}if(el.dataset.roleMode){state.role=el.dataset.roleMode;render();return}if(el.dataset.profileRole){state.profileRole=el.dataset.profileRole;render();return}
 switch(el.dataset.action){case'studio-broaden':Object.assign(state,{type:'all',hand:'all',count:'all',studioArm:'all',studioCount:'all',studioCell:'all',studioPair:'all',studioBin:'all'});render();break;case'studio-clear':state.studioCount=state.studioCell=state.studioPair=state.studioBin='all';render();break;case'studio-export':downloadCSV('centre-atlas-study.csv',pitchCSV(studioSelection(studioRows(),current.pitches,state),I));break;case'clear-situation':Object.assign(state,{...roomDefaults,roomRole:state.roomRole,type:'all',hand:'all',count:'all'});render();break;case'room-export':downloadCSV('centre-atlas-situation.csv',pitchCSV(roomRows(pitches(state.roomRole),state,I),I));break;case'theme':toggleTheme();break;case'search':openSearch();break;case'reset':reset();break;case'retry':render();break;case'play':playReplay();break;case'share':share();break;case'sensitivity':state.sensitivity=!state.sensitivity;render();break;case'export':exportRows(el.dataset.role);break;case'all-samples':state.minimum=state.minimum?0:20;render();break}
});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}if(e.target.matches('th[data-sort]')&&(e.key==='Enter'||e.key===' ')){e.preventDefault();sortTable(e.target)}});
for(const d of document.querySelectorAll('dialog'))d.addEventListener('click',e=>{if(e.target===d)d.close()});
let lastPage=currentPage();window.addEventListener('hashchange',()=>{const pg=currentPage();if(pg!==lastPage){state.person='all';state.type='all';state.hand='all';state.count='all';state.query='';state.profileRole='auto';lastPage=pg}window.scrollTo({top:0,behavior:'instant'});render()});
async function init(){try{const loaded=await Promise.all([fetchJSON('data/index.json'),fetchJSON('assets/players/portraits.json').catch(()=>({players:{}}))]);I=loaded[0];photos=loaded[1];installPortraitFallback();if(!I.seasons.includes(state.season)&&state.season!=='All seasons')state.season='Fall 2026';try{const view=JSON.parse(new URL(location.href).searchParams.get('view')||'null');if(view&&typeof view==='object'){for(const k of viewKeys)if(typeof view[k]==='string'||k==='sensitivity'&&typeof view[k]==='boolean')state[k]=view[k];if(!I.seasons.includes(state.season)&&state.season!=='All seasons')state.season='Fall 2026'}}catch{}shell();await render();const uid=new URL(location.href).searchParams.get('pitch');if(uid)await inspectPitch(uid)}catch(e){app.innerHTML=empty('Atlas could not start.',esc(e.message),'<button onclick="location.reload()">Reload</button>');console.error(e)}}
init();
